import React, { useState } from 'react';
import MenuCategories from './Menu/MenuCategories';
import MenuItems from './Menu/MenuItems';
import CustomerSearch from './Customer/CustomerSearch';
import './StyleGuide.css';

const StyleGuide = () => {
  const [selectedCategory, setSelectedCategory] = useState(1);
  const [cartItems, setCartItems] = useState([
    {
      id: 1,
      name: 'Bulgogi Rice Bowl',
      price: 18.50,
      quantity: 2,
      selectedOptions: {
        spice: 'mild',
        toppings: ['cheese']
      },
      displayPrice: 20.50,
      cartId: 'demo1'
    },
    {
      id: 2,
      name: 'Kimchi Fried Rice',
      price: 15.90,
      quantity: 1,
      cartId: 'demo2'
    }
  ]);

  const mockCategories = [
    { id: 1, name: 'Korean Food' },
    { id: 2, name: 'Japanese' },
    { id: 3, name: 'Western' },
    { id: 4, name: 'Beverages' },
    { id: 5, name: 'Desserts' }
  ];

  const handleAddToCart = (item) => {
    console.log('Added to cart:', item);
  };

  return (
    <div className="style-guide">
      <h1>POS System Style Guide</h1>

      {/* Menu Categories */}
      <div className="guide-section">
        <h2>Menu Categories</h2>
        <MenuCategories 
          categories={mockCategories}
          onCategorySelect={setSelectedCategory}
          selectedCategory={selectedCategory}
        />
      </div>

      {/* Menu Items */}
      <div className="guide-section">
        <h2>Menu Items - Card Style</h2>
        <MenuItems onAddToCart={handleAddToCart} />
      </div>

      {/* Cart Items Demo */}
      <div className="guide-section">
        <h2>Cart Items with Options (장바구니에서 옵션 수정)</h2>
        {cartItems.map(item => (
          <div key={item.cartId || item.id} className="cart-item-demo">
            <div className="cart-item-info">
              <span className="cart-item-name">{item.name}</span>
              {item.selectedOptions && Object.keys(item.selectedOptions).length > 0 && (
                <div className="cart-item-options">
                  {Object.entries(item.selectedOptions).map(([optionType, selectedValue]) => {
                    if (Array.isArray(selectedValue)) {
                      return selectedValue.map(valueId => (
                        <span key={valueId} className="option-tag">{valueId}</span>
                      ));
                    } else {
                      return <span key={optionType} className="option-tag">{selectedValue}</span>;
                    }
                  }).flat()}
                </div>
              )}
              <span className="cart-item-qty">x{item.quantity}</span>
            </div>
            <div className="cart-item-actions">
              <span className="cart-item-price">RM {((item.displayPrice || item.price) * item.quantity).toFixed(2)}</span>
              <button className="btn-option-edit">Options</button>
              <button className="btn-remove">×</button>
            </div>
          </div>
        ))}
      </div>

      {/* Customer Search */}
      <div className="guide-section">
        <h2>Customer Search</h2>
        <CustomerSearch 
          selectedCustomer={{ id: 1, name: 'Walk-in Customer', type: 'walk-in' }}
          onCustomerSelect={() => {}}
        />
      </div>
    </div>
  );
};

export default StyleGuide;
